Thay đổi các biến thể chính là gì? Ngôn ngữ lập trình C Trong bài tập 1-16 trong cuốn sách "The C Programming Language" (K&R), nó yêu cầu chúng ta: sửa đổi hàm _main_ của chương trình đo chiều dài dòng dài nhất để in ra độ dài của các dòng đầu vào tùy ý và nhiều văn bản nhất có thể. Từ những gì tôi đọc ở đây, tôi nhận được ý tưởng rằng hàm main là mọi thứ nằm trong hàm main, điều này có chính xác không? Tôi đăng mã nguồn của chương trình đo chiều dài dòng dài nhất bên dưới để cung cấp thêm ngữ cảnh, nhưng tôi bối rối về những gì tôi được yêu cầu làm, không phải là mã. Cảm ơn!

#include <stdio.h>

#define MAXLINE 1000 /* độ dài dòng đầu vào tối đa */

int getline(char line[], int maxline);

void copy(char to[], char from[]);

/* in ra dòng dài nhất */

main()

{

int len; /* độ dài dòng hiện tại */

int max; /* độ dài tối đa cho đến nay */

char line[MAXLINE]; /* dòng đầu vào hiện tại */

char longest[MAXLINE]; /* dòng dài nhất được lưu trữ ở đây */

max = 0;

while ((len = getline(line, MAXLINE)) > 0)

if (len > max) {

max = len;

copy(longest, line);

}

if (max > 0)

printf("%s", longest);

return 0;

}

/* getline: đọc một dòng vào s, trả về độ dài */

int getline(char s[], int lim)

{

int c, i;

for (i = 0; i < lim - 1 && (c = getchar()) != EOF && c != '\n'; ++i)

s[i] = c;

if (c == '\n') {

s[i] = c;

++i;

}

s[i] = '\0';

return i;

}

/* copy: sao chép 'from' vào 'to'; giả sử to đủ lớn */

void copy(char to[], char from[])

{

int i;

i = 0;

while ((to[i] = from[i]) != '\0')

++i;

}

Entity Framework 5 - Tách logic nghiệp vụ ra khỏi mô hình - Repository? Tôi đang làm việc trên ứng dụng web đầu tiên của mình và tôi đang sử dụng MVC 4 cho lớp trình bày và EF 5 cho DAL. Cấu trúc cơ sở dữ liệu được khóa, và có sự khác biệt vừa phải giữa cách người dùng nhập dữ liệu và cách cơ sở dữ liệu được tạo dữ liệu. Tôi đã đọc rất nhiều về mô hình kho (mô hình mà tôi chưa từng sử dụng) nhưng hầu hết các nghiên cứu của tôi đều khiến tôi không muốn sử dụng nó vì nó tạo ra một mức độ trừu tượng không cần thiết cho các phiên bản mới nhất của EF do các kho lưu trữ và đơn vị-của-làm việc đã được tích hợp sẵn. Cách tiếp cận ban đầu của tôi là chỉ tạo một tập hợp các lớp cho các đối tượng kinh doanh trong BLL có thể hoạt động như một trung gian giữa các bộ điều khiển và DAL của tôi. Đây là một ví dụ về lớp:

public class MyBuilding
{
    public int Id { get; private set; }
    public string Name { get; set; }
    public string Notes { get; set; }

    private readonly Entities _context = new Entities(); // Liệu điều này có an toàn cho luồng?

    private static readonly int UserId = WebSecurity.GetCurrentUser().UserId;

    public IEnumerable<MyBuilding> GetList()
    {
        IEnumerable<MyBuilding> buildingList =
            from p in _context.BuildingInfo
            where p.Building.UserProfile.UserId == UserId
            select new MyBuilding { Id = p.BuildingId, Name = p.BuildingName, Notes = p.Building.Notes };

        return buildingList;
    }

    public void Create()
    {
        var b = new Building { UserId = UserId, Notes = this.Notes };
        _context.Building.Add(b);
        _context.SaveChanges();

        // Thiết lập ID của tòa nhà
        this.Id = b.BuildingId;

        // Gieo hạt cho các bảng 1-đến-1 tham chiếu đến tòa nhà mới
        _context.BuildingInfo.Add(new BuildingInfo { Building = b });
        _context.GeneralInfo.Add(new GeneralInfo { Building = b });
        _context.LocationInfo.Add(new LocationInfo { Building = b });
        _context.SaveChanges();
    }

    public static MyBuilding Find(int id)
    {
        using (var context = new Entities()) // Liệu điều này có ổn để thực hiện trong một phương thức tĩnh?
        {
            var b = context.Building.FirstOrDefault(p => p.BuildingId == id && p.UserId == UserId);
            if (b == null) throw new Exception("Lỗi: Tòa nhà không tìm thấy hoặc người dùng không có quyền truy cập.");
            return new MyBuilding { Id = b.BuildingId, Name = b.BuildingInfo.BuildingName, Notes = b.Notes };
        }
    }
}

Quan tâm chính của tôi: Cách tôi khởi tạo DbContext như một thuộc tính riêng tư có an toàn cho luồng hay không, và có an toàn khi có một phương thức tĩnh khởi tạo một DbContext riêng biệt không? Hoặc tôi đang tiếp cận vấn đề này theo cách hoàn toàn sai lầm? Tôi không phản đối việc học hỏi về mô hình kho nếu cách tiếp cận của tôi hoàn toàn sai.

Liệu có thể bao gồm đối tượng chính nó trong một thuộc tính động không? Tôi hỏi câu này vì tò mò. Hãy giả sử lớp Foo là một singleton và tôi muốn gọi Foo thay vì Foo.Instance để truy cập đối tượng tĩnh. Liệu có thể đóng gói đối tượng chính nó trong một thuộc tính động không? C# có cho phép tôi tạo một thuộc tính động mà đề cập đến bất cứ điều gì nhưng không phải là thuộc tính của đối tượng đã nói? Như sau:

private static Foo _instance;

public static Foo this
{
    get
    {
        if (_instance == null)
        {
            _instance = new Foo();
        }

        return _instance;
    }
}

public void Bar() {}

Điều này sẽ cho phép tôi gọi

Foo.Bar();

thay vì

Foo.Instance.Bar();

Nếu điều đó là có thể, sau đó trong trường hợp nào sẽ khả thi để đóng gói mọi loại đối tượng như vậy mà không sử dụng thừa kế ví dụ thay vì:

class Ploof : List {}

chúng ta sẽ có:

class Ploof
{
    private List _list;

    public List this
    {
        get
        {
            return _list;
        }
    }
}

Khi nào tôi nên truyền giá trị như biến lớp và khi nào như một đối số phương thức? Có một quy tắc chung, khi nào chúng ta nên truyền một giá trị như một biến lớp và khi nào như một đối số phương thức? Hoặc nó chỉ là sự lựa chọn của nhà phát triển? Ví dụ -- có lý do gì khiến mã sau (mã PHP) tốt hơn (hoặc tệ hơn?) so với mã này không:

    class SomeClass
    {
        public function __construct()
        {
            $this->id = $_GET['id'];
            $this->showMessage();
        }

        public function showMessage()
        {
            echo 'The ID is '.$this->id;
        }
    }

so với mã này:

    class SomeClass
    {
        public function __construct()
        {
            $this->showMessage($_GET['id']);
        }

        public function showMessage($id)
        {
            echo 'The ID is '.$id;
        }
    }

Lưu ý rằng tôi chỉ hỏi về sự khác biệt giữa việc truyền giá trị như một biến lớp và truyền như một đối số phương thức. Vui lòng đừng nói rằng tôi không bao giờ nên vận hành trực tiếp trên các siêu toàn cầu trong PHP. Tôi biết điều đó là sai. Tôi đã sử dụng nó ở đây để đơn giản hóa ví dụ.

Có cách nào để tăng tốc mã PHP của tôi phân tích các tập tin XML Tôi đang phát triển một ứng dụng web và chúng tôi sử dụng XML làm cơ sở dữ liệu và tôi sử dụng Linux làm nền tảng và CentOS 6.5 làm máy chủ. Việc thay đổi một số giá trị sẽ tạo ra rất nhiều thay đổi trong khoảng sáu tập tin XML. Và đây là vấn đề: Nhấn nút lưu sau khi chỉnh sửa, thêm, xóa mất khoảng một phút hoặc một phút rưỡi hoặc nhiều hơn! Điều này là do mã của tôi phải cập nhật khoảng sáu tập tin XML, tập tin nhật ký và tập tin crontab. Tôi tự hỏi có gì giống như luồng trong PHP không? Tôi có các hàm và tất cả mã tôi muốn, tôi chỉ muốn biết cách PHP có thể được sử dụng theo một cách mới để cải thiện hiệu suất. Bạn có thể hướng dẫn tôi ngay cả bằng liên kết để đọc không? Tôi không biết chính xác vấn đề này được gọi là gì để tìm kiếm về nó. Tôi vẫn còn là người mới bắt đầu. Đây là hàm cập nhật mà tôi đang sử dụng:

public static function update($tableName, $fieldsToUpdate, $newValues, $value = NULL) {
//Tải tập tin XML
$fileName = G_APP_SCRIPTS_PATH . "/XMLS/xmls/" . $tableName . ".xml";
$xml = new DOMDocument;
$xml->load($fileName);

//Tải tập tin XSD
$xsdfileName = G_APP_SCRIPTS_PATH . "/XMLS/xsds/" . $tableName . ".xsd";
$xsd = new DOMDocument;
$xsd->load($xsdfileName);

//Tạo XPath
$path = c_XML::generateXPath($xml, $xsd, $fieldsToUpdate, $value);
$xpath = new DOMXPath($xml);

//Truy vấn các nút để cập nhật
$nodes = $xpath->query($path);
//        print_r($nodes->item(0));

//Nếu số lượng các giá trị mới < số lượng các phần tử để cập nhật, có nghĩa là chúng ta phải cập nhật
//tất cả các phần tử được chỉ định trong XML mà không có điều kiện nào
if (count($newValues) < $nodes->length) {
for ($i = 0; $i < $nodes->length / count($newValues); $i++)
$newValues = array_merge($newValues, $newValues);
}

//Lặp qua các nút để cập nhật
for ($i = 0; $i < $nodes->length; $i++) {
$oldNode = $nodes->item($i);
for ($index = 0; $index < count($fieldsToUpdate); $index++) {
//Tìm chỉ mục liên quan trong mảng $fieldsToUpdate
if (strcmp($oldNode->nodeName, $fieldsToUpdate[$index]) === 0) {
break;
}
}

//Tạo nút mới với tên của nút cũ
$newNode = $xml->createElement($oldNode->nodeName);
//var_dump($newNode);
//nếu giá trị mới là một mảng, có nghĩa là chúng ta phải cập nhật một nút bên trong
if (is_array($newValues[$index])) {
//đi đến nút mong muốn trong XSD và lấy các phần tử con của nó,
//để biết định dạng của chúng
$xsdxpath = new DOMXPath($xsd);
$children = $xsdxpath->query("/xs:schema/xs:element/xs:complexType/xs:sequence/xs:element/xs:complexType/xs:sequence/xs:element[@name='" . $oldNode->nodeName . "']/xs:complexType/xs:sequence/xs:element");
//chuyển danh sách nút con thành một mảng để truyền cho hàm createNode.
for ($c = 0; $c < $children->length; $c++) {
$childrenArray[$c] = $children->item($c);
}

//tạo nút mong muốn
c_XML::createNode($xml, $xsdxpath, $newNode, $childrenArray, $newValues[$index]);
}

//Nếu giá trị mới không phải là một mảng
else
$newNode->nodeValue = $newValues[$index];

//Thay thế nút cũ bằng nút mới
$parent = $oldNode->parentNode;
$parent->replaceChild($newNode, $oldNode);
}

//Xác nhận & lưu XML
$isValid = c_XML::validateXMLtoXSD($xml, $xsdfileName);
if ($isValid == 1) {
$xml->save($fileName);
return true;
}
else
return false;
}

và khi người dùng cập nhật một giá trị, tôi sử dụng cách này để cập nhật các tập tin XML khác:

private static function change_value_in_xml_file($old_value, $new_value) {
$all_nodes = c_XML_h::select(tables::xmlfile, '*');
$nodes = array();
for ($i = 0; $i < count($all_nodes); $i++) {
$nodes[$i] = array();
//chỉ lấy các nút tôi muốn
$nodes[$i][0] = $all_nodes[$i][0];
$nodes[$i][1] = $all_nodes[$i][3];
}

//tìm giá trị cũ và thay thế nó bằng giá trị mới
foreach ($nodes as $node) {
$newValues[0] = $new_value;
if ($node[1] == $old_value) {
$id_to_update = $node[0];
$fieldsToSelect[0] = xmlfile:: value;
c_XML_h::update(tables::xmlfile, $fieldsToSelect, $newValues, $id_to_update);
}
}
}

Tên mẫu phải được đặt như thế nào? Trong D tôi có thể tạo ra các mẫu như thế này:

