Thêm một phương pháp mới vào thư viện lớp cho phiên bản mới của nó và hiển thị tùy chọn phiên bản người dùng có thể chọn Liệu có phải là một ý tưởng tồi khi thêm một phương thức (thực hiện một thuật toán mới) vào thư viện lớp cho phiên bản mới và hiển thị một tùy chọn phiên bản mà người tiêu dùng có thể chọn? Đó chỉ là để tương thích ngược nơi mà một ứng dụng cũ có thể cần một chuỗi số ngẫu nhiên thường xuyên cho một số hạt giống nhất định. Mã sau đây có thể nói rõ ý tưởng của tôi tốt hơn. Hy vọng bạn nắm được bản chất của nó.

// Thư viện lớp:

namespace MyGenerator
{
public sealed class MyRandom
{
public enum Version { One, Two } // thêm các tùy chọn trong tương lai
private int current;
private Version version;
public MyRandom(int seed, Version version = Version.One)
{
current = seed;
this.version = version;
}
public int Next()
{
switch (version)
{
case Version.One:
AlgorithmOne();
break;
case Version.Two:
AlgorithmTwo();
break;
// thêm các tùy chọn trong tương lai
}
return current;
}
private int AlgorithmOne()
{
current = (current * 1234567890 + 987654321) & 0x7FFFFFFF;
return current;
}
private int AlgorithmTwo()
{
current = (current * current + current) & 0x7FFFFFFF;
return current;
}
// thêm thuật toán trong tương lai
}
}

và

// Ứng dụng Console (cho mục đích thử nghiệm):

using MyGenerator;
using System;
namespace ConsoleApplication1
{
class Program
{
static void Main(string[] args)
{
const int seed = 12345;
MyRandom rnd = new MyRandom(seed, MyRandom.Version.Two);
Console.WriteLine(rnd.Next());
Console.ReadLine();
}
}
}

Phân nhánh hai lần cho điều kiện duy nhất Hãy xem xét một ứng dụng hiển thị chỉ các Foobar thuộc quyền sở hữu của chính họ cho người dùng bình thường, và tất cả các Foobar cho quản trị viên:

-- Người dùng bình thường:
SELECT * FROM Foobar WHERE user_id=:user_id;

-- Quản trị viên:
SELECT * FROM Foobar;

Hiện tại, đây là cách các câu truy vấn được thể hiện trong mã nguồn:

$sql = "SELECT * FROM Foobar";
if ( $user['type']!='admin' ) {
$sql.= ' WHERE user_id=:user_id';
}
$stmt = $pdo->prepare($sql);
if ( $user['type']!='admin' ) {
$stmt->bindValue(':user_id', $user['id']);
}
Tôi không thích cách tiếp cận phân nhánh kép này từ quan điểm bảo trì. Ví dụ, lỗi như gõ $user['type']=='admin' thay vì $user['type']!='admin' sẽ phải được tìm kiếm và sửa chữa ở hai vị trí thay vì một. Tuy nhiên, tôi cũng không thích ý tưởng về các hàm riêng biệt cho mỗi trường hợp: quản trị viên và người dùng thông thường. Một cách tiếp cận thứ ba sẽ là phân nhánh một lần và sau đó tạo ra câu SQL để thêm và các giá trị để ràng buộc:

$sql_to_add = '';
$array_to_bind = array();
if ( $user['type']!='admin' ) {
$sql_to_add = ' WHERE user_id=:user_id';
$array_to_bind = array( ':user_id'=>$user['id'] );
}
$sql = "SELECT * FROM Foobar {$sql_to_add}";
$stmt = $pdo->prepare($sql);
foreach ( $array_to_bind as $k=>$v ) {
$stmt->bindValue($k, $v);
}
Tuy nhiên, tôi thấy cách tiếp cận này khá cồng kềnh. **Có một mẫu thiết kế nào cho tình huống này không?** Cách tiếp cận chuẩn mực để xử lý các tình huống mà mã phải phân nhánh ở hai vị trí riêng biệt trên cùng một điều kiện if là gì?

Cấu trúc dữ liệu hướng đối tượng trong các ứng dụng do cơ sở dữ liệu điều khiển Tôi đã bắt đầu làm việc cho một công ty duy trì một trang web thương mại cỡ nhỏ/trung bình. Trang web được viết bằng c# asp.net, và sử dụng SQL Server như một cơ sở dữ liệu. Cấu trúc mã hiện tại rất lộn xộn (ví dụ, tập tin `Utility.cs` khoảng 5000 dòng) vì vậy tôi muốn tiến tới một thiết kế tốt hơn về phía ứng dụng asp.net. Tôi đang cố gắng tìm ra cách thực hiện đúng đắn. Kế hoạch cơ bản của tôi là tạo một lớp cho mỗi mục riêng biệt về mặt logic trong ứng dụng (phần lớn ánh xạ 1-1 với bảng cơ sở dữ liệu, nhưng đôi khi N-1 hoặc 1-N). Sau đó, tôi dự định có một số phương thức nhà máy tĩnh để khởi tạo các lớp này bằng cách truy vấn cơ sở dữ liệu. Nhà phát triển nên có thể thao tác đối tượng kết quả, và sau đó sử dụng phương thức `UpdateDatabase()` để lưu các thay đổi vào cơ sở dữ liệu. Ví dụ, đây là cách hoạt động của một đối tượng `Email`:

