Cách tốt nhất để hiển thị thông tin tóm tắt đối tượng domain hiệu quả và theo cách hướng đối tượng từ một cây thừa kế lớn? Tôi chỉ cung cấp mã đơn giản vì đây là câu hỏi về thiết kế trừu tượng. Vì vậy tôi có rất nhiều đối tượng sự kiện kinh doanh/ngành, ví dụ:

public class Event { //hàng tá thuộc tính và phương thức truy cập tiêu chuẩn }

public class ExplosionEvent extends Event { //thuộc tính và phương thức truy cập tiêu chuẩn }

Và còn rất nhiều đối tượng khác ở các cấp độ khác nhau. Nếu tôi cần thông tin về bất kỳ đối tượng nào được chọn, tôi hiển thị nó trong HTML như sau

private String generateHTML(Event event) { StringBuilder sb = new StringBuilder(); sb.append("<HTML><table>"); //đơn giản hóa sb.append("<TH>Thời gian</TH>"); sb.append("<TD>" + event.getEventTime() + "</TD>"); if (event instanceof ExplosionEvent) { //thêm HTML và dữ liệu cụ thể của ExplosionEvent } // ...nhiều, nhiều cuộc gọi giống như trên sb.append("</table></HTML>"); }

Vì tôi có nhiều loại sự kiện, điều này có nghĩa là rất nhiều thẻ bảng HTML trùng lặp và sử dụng 'instanceof' nên phương thức generateHTML dài hàng trăm dòng, chia thành các phương thức khác nhưng vẫn còn rất nhiều mã khiến việc hiểu, điều hướng và bảo trì khó khăn. Điều này rất xấu và tôi cần một thiết kế tốt hơn cho vấn đề này. Tôi đã nghĩ đến việc tạo một phương thức trong lớp 'Event' có thể ghi đè bởi tất cả các lớp con

//Sử dụng LinkedHashMap để bảo tồn thứ tự vì Properties sẽ không làm điều đó public LinkedHashMap<String, String> getAttributes() { LinkedHashMap<String, String> list = new LinkedHashMap<String, String>(); list.put("Thời gian", eventTime); }

các lớp con sau đó ghi đè phương thức này, gọi phương thức của lớp cha và thêm dữ liệu cụ thể cho chúng vào danh sách có nghĩa là bất kể có bao nhiêu lớp 'Event', phương thức generateHTML (ngoài đối tượng 'Event') sau đó sẽ chỉ là một vòng lặp nhỏ

private String generateHTML(Event event) { StringBuilder sb = new StringBuilder(); sb.append("<HTML><table>"); for (Entry<String, String> entry : event.getAttributes().entrySet()) { sb.append("<TH>" + entry.getKey() + "</TH>"); sb.append("<TD>" + entry.getValue() + "</TD>"); } sb.append("</table></HTML>"); }

Điều này có đặt quá nhiều logic vào các đối tượng kinh doanh/ngành không? **Có cách nào tốt hơn không**?

Mã thuật toán nào nhanh hơn? Tôi đang tạo một trò chơi nhỏ, trong đó máy tính sẽ tạo ra số ngẫu nhiên giả trong khoảng cho trước và người dùng phải đoán nó. Tôi cũng đã tạo thêm tùy chọn để chơi máy tính đấu máy tính. Tôi muốn máy tính tạo ra số ngẫu nhiên và máy tính phải đoán được con số đó. Cách đơn giản nhất tôi tìm ra là sử dụng vòng lặp for và tăng một biến cho đến khi nó đoán đúng. Tuy nhiên, tôi quyết định thử tạo thuật toán riêng của mình về vấn đề này. Về cơ bản, biến chứa số đoán được bằng với khoảng chia đôi, sau đó chương trình vào vòng lặp while và nếu số ngẫu nhiên lớn hơn số được tạo ra bằng logic (số bằng khoảng chia đôi) thì chia nó cho 2 và cộng thêm 1. Nếu số nhỏ hơn, chương trình nhân nó với 2 và cộng thêm 1 cho đến khi đoán đúng con số. Đây là mã C++:

void aiVsAI(int range){
    // range argument is used to be given to the randome generator func
    int random_number = generate_random_number(range); // gán số ngẫu nhiên vào biến
    int guess = range / 2; // số máy tính đoán
    int tries = 0; // số lần máy tính cần đoán
    while(guess != random_number){ // khi số đoán chưa bằng số ngẫu nhiên
        if(guess > random_number){ // nếu số đoán lớn hơn số ngẫu nhiên
            guess = guess / 2 + 1; // chia nó cho 2 và cộng thêm 1
        }
        else if(guess < random_number){ // nếu số nhỏ hơn số ngẫu nhiên
            guess = guess * 2 + 1; // nhân nó với 2 và cộng thêm 1
        }
        tries++; // tăng số lượt đoán
    }
    std::cout << tries;
}

generate_random_number là hàm sẽ tạo ra số ngẫu nhiên giả. Vậy thuật toán này có nhanh hơn so với việc sử dụng vòng lặp for và tăng biến lên 1 cho đến khi đoán đúng hay không?

Đây là mã đầy đủ nếu ai đó cần nó cho điều gì đó:

#include <iostream>
#include <string>
#include <cstdlib>
#include <time.h>

// hàm tạo ra số ngẫu nhiên
int generate_random_number(int range){
    // range argument là giá trị tối đa của số
    if(range < 10){
        std::cout << "range không thể nhỏ hơn 10 nhưng có thể bằng";
        exit(1);
    }
    srand(time(NULL)); // đảm bảo rằng số ngẫu nhiên sẽ khác nhau mỗi lần
    return rand() % range; // trả về số ngẫu nhiên trong khoảng cho trước
}

// Trò chơi máy tính đấu máy tính
void aiVsAI(int range){
    int random_number = generate_random_number(range); // gán số ngẫu nhiên vào biến
    int guess = range / 2; // số máy tính đoán
    int tries = 0; // số lần máy tính cần đoán
    while(guess != random_number){ // khi số đoán chưa bằng số ngẫu nhiên
        if(guess > random_number){ // nếu số đoán lớn hơn số ngẫu nhiên
            guess = guess / 2 + 1; // chia nó cho 2 và cộng thêm 1
        }
        else if(guess < random_number){ // nếu số nhỏ hơn số ngẫu nhiên
            guess = guess * 2 + 1; // nhân nó với 2 và cộng thêm 1
        }
        tries++; // tăng số lượt đoán
    }
    std::cout << tries;
}

// Trò chơi người dùng đấu máy tính
void humanVsAI(int range){
    int random_number = generate_random_number(range); // gán số ngẫu nhiên vào biến
    int input = 0; // biến đại diện cho đầu vào của người dùng
    int tries = 0; // số lần người dùng đoán
    while(input != random_number){
        std::cout << "Nhập số: "; // nhắc người dùng nhập số
        std::cin >> input; // nhận số
        if(input < random_number) // kiểm tra nếu số lớn hơn số ngẫu nhiên
            std::cout << "Bạn chưa đoán đúng, bạn đoán thấp quá, hãy thử lại!\n"; // nhắc nhở người dùng
        else{ // nếu không, số đó lớn hơn số ngẫu nhiên
            std::cout << "Bạn chưa đoán đúng, bạn đoán cao quá, hãy thử lại!\n"; // nhắc nhở người dùng
        }
        tries++; // tăng số lượt đoán lên 1 cho mỗi lượt đoán
    }
    std::cout << "\n\nBạn đoán đúng rồi! Bạn cần " << tries << " lượt để làm được điều này.\n\n";
}

// Trò chơi người dùng đấu người dùng
void humanVsHuman(int range){
    int number_to_guess; // số phải đoán
    int user_guess; // đầu vào của người dùng
    int guess;
    std::cout << "Nhập số trong khoảng từ 1-"<< range<<": \n"; // nhắc người dùng nhập số
    std::cin >> number_to_guess; // nhập số
    for(int i = 0; i < 100;i++){ // Xóa màn hình
        std::cout << "\n";
    }
    while(user_guess != number_to_guess){
        guess++;
        std::cout << "Vui lòng nhập số:\n"; // nhắc người dùng nhập số
        std::cin >> user_guess; // Nhận đầu vào của người dùng
        if(user_guess < number_to_guess)
            std::cout << "Bạn chưa đoán đúng, bạn đoán thấp quá, hãy thử lại!\n";
        else if(user_guess > number_to_guess)
            std::cout << "Bạn chưa đoán đúng, bạn đoán cao quá, hãy thử lại!\n";
    }
    std::cout << "Bạn đoán đúng số\n";
}

