nền: -webkit-gradient (tuyến tính, trái trên, phải trên, từ (#2F2727), dừng màu sắc (0,05, # 1a82f7), dừng màu sắc (0,5, # 2F2727), dừng màu sắc (0,95, # 1a82f7), đến (#2F2727));
/* Safari 5.1+, Chrome 10+ */
