            return $product;
        }
    }

Tôi nghĩ phương pháp 2 có phần linh hoạt hơn và cho phép tôi thêm các hàm khác sau này, chẳng hạn như tải các tập hợp dữ liệu khác nhau từ các tập hợp tham số khác nhau. Sự linh hoạt này có thể hữu ích trong trường hợp codebase cũ gây bất ngờ cho tôi sau này. (ví dụ: khi tôi tái cấu trúc, tôi có thể nhận ra mình cần di chuyển hoặc nhóm phần tải dữ liệu này với một phần mã khác và việc đóng gói mã cung cấp sẽ dễ dàng di chuyển nó sang nơi khác). Mẫu ví dụ thứ hai của tôi có phải là sự phù hợp chính xác cho ví dụ tái cấu trúc của tôi không?

Tạo một đối tượng đã sẵn sàng để sử dụng và chưa được thiết lập thuộc tính - với IoC Tôi có một câu hỏi liên quan đến các đặc điểm của việc tạo đối tượng và sử dụng thuộc tính. Một phương pháp thực hành tốt là đặt tất cả các thuộc tính vào một trạng thái sao cho đối tượng hữu ích khi nó được tạo ra. Các hàm tạo đối tượng giúp đảm bảo rằng các phụ thuộc cần thiết được tạo ra. Tôi thấy mình đã đi theo một mô hình gần đây, và sau đó tự hỏi về sự phù hợp của nó. Mô hình này trông như thế này...

public class ThingProcesser
{
public List<Thing> CalculatedThings { get; set; }

public ThingProcesser()
{
CalculatedThings = new List<Thing>();
}

public double FindCertainThing()
{
CheckForException();
foreach (var thing in CalculatedThings)
{
// làm một số việc với các đối tượng...
}
}

public double FindOtherThing()
{
CheckForException();
foreach (var thing in CalculatedThings)
{
// làm một số việc với các đối tượng...
}
}

private void CheckForException()
{
if (CalculatedThings.Count < 2) throw new InvalidOperationException("Các đối tượng được tính toán phải có nhiều hơn 2 mục");
}
}

Danh sách các mục không thay đổi, chỉ được duyệt qua bởi các phương thức. Có nhiều phương thức trong lớp, và để tránh phải truyền danh sách các đối tượng cho mỗi hàm như một tham số phương thức, tôi thiết lập nó một lần trên lớp. Mặc dù điều này hoạt động, nhưng nó có vi phạm nguyên tắc ít ngạc nhiên nhất không? Từ khi bắt đầu sử dụng IoC, tôi thấy mình không gán các đối tượng vào hàm tạo, để tránh phải sử dụng mẫu nhà máy. Ví dụ, tôi có thể tranh luận với chính mình và nói rằng thực sự ThingProcessor cần một List để hoạt động, vì vậy đối tượng nên được tạo ra như thế này.

public class ThingProcesser
{
public List<Thing> CalculatedThings { get; set; }

public ThingProcesser(List<Thing> calculatedThings)
{
CalculatedThings = calculatedThings;
}
}

Tuy nhiên, nếu tôi làm như vậy, nó sẽ làm phức tạp vấn đề cho IoC, và kịch bản này dường như không phù hợp với một cái gì đó giống như mẫu nhà máy. Tóm lại, có những hướng dẫn tốt nào cho khi nào một thứ gì đó nên là một phần của trạng thái đối tượng, so với việc được truyền như một tham số phương thức? Khi sử dụng IoC, mẫu nhà máy có phải là cách tốt nhất để xử lý các đối tượng cần được tạo ra với trạng thái? Nếu một cái gì đó phải được truyền cho nhiều phương thức trong một lớp, điều đó có khiến nó trở thành một ứng cử viên tốt để là một phần của trạng thái đối tượng không?

Khi nào tôi nên sao chép một con trỏ bên trong một hàm? Tôi đang cố gắng tự học lập trình và tôi thực sự mong muốn được giúp đỡ về vấn đề này. Tôi vừa đọc một hướng dẫn về con trỏ nhưng tôi gặp khó khăn với ví dụ này. Hàm này sao chép một chuỗi sang một chuỗi khác. Trong hàm gốc, bản sao được thực hiện bằng cách sử dụng ptr. Ý nghĩa của điều này là gì? Bởi vì theo quan điểm của tôi, nó không cần thiết. Có lỗi gì trong hàm sửa đổi của tôi hay tôi đã bỏ lỡ điều gì đó?

