Vấn đề với mã C. Raspberry PI, HD44780 LCD Tôi đang viết một chương trình giao tiếp giữa Raspberry Pi với màn hình LCD HD44780. Mã code tôi viết dường như không khởi tạo được màn hình, theo dữ liệu bảng kỹ thuật thì tôi nghĩ mình đã thực hiện đúng quy trình. Tôi biết mã này không tốt nhưng tôi chỉ tập trung vào việc làm cho nó hoạt động rồi mới chỉnh sửa và cải thiện sau. Đây là để giúp tôi học C. Tôi đang sử dụng thư viện bcm2835 của mikem. Mã code như sau:

#include <stdio.h>
#include <bcm2835.h>

#define RS RPI_GPIO_P1_26 // GPIO 7
#define En RPI_GPIO_P1_24 // GPIO 8
#define D4 RPI_GPIO_P1_11 // GPIO 17
#define D5 RPI_GPIO_P1_12 // GPIO 18
#define D6 RPI_GPIO_P1_13 // GPIO 27
#define D7 RPI_GPIO_P1_15 // GPIO 22

#define FUNC_4b_2L_5X8 0x28
#define DISP_ON_CURS_ON_BLINK_OFF 0x0E
#define INC_ON_SHIFT_OFF 0x06
#define CNTRL_LINES_LOW 0xFFF8
#define CURS_LEFT 0x10
#define CURS_RIGHT 0x14
#define CLR_DISP 0x01
#define SHIFT_LEFT 0x18
#define SHIFT_RIGHT 0x1C
#define ROW_0_START 0x80
#define ROW_1_START 0xC0
#define RETURN_HOME 0x2

void lcd_gpio_low(void)
{
    bcm2835_gpio_write(RS, LOW);
    bcm2835_gpio_write(En, LOW);
    bcm2835_gpio_write(D4, LOW);
    bcm2835_gpio_write(D5, LOW);
    bcm2835_gpio_write(D6, LOW);
    bcm2835_gpio_write(D7, LOW);
}

void assign_bits(uint8_t data)
{
    switch(data)
    {
        case 0:
            bcm2835_gpio_write(D4, LOW);
            bcm2835_gpio_write(D5, LOW);
            bcm2835_gpio_write(D6, LOW);
            bcm2835_gpio_write(D7, LOW);
            break;

        case 1:
            bcm2835_gpio_write(D4, HIGH);
            bcm2835_gpio_write(D5, LOW);
            bcm2835_gpio_write(D6, LOW);
            bcm2835_gpio_write(D7, LOW);
            break;

        case 2:
            bcm2835_gpio_write(D4, LOW);
            bcm2835_gpio_write(D5, HIGH);
            bcm2835_gpio_write(D6, LOW);
            bcm2835_gpio_write(D7, LOW);
            break;

        case 3:
            bcm2835_gpio_write(D4, HIGH);
            bcm2835_gpio_write(D5, HIGH);
            bcm2835_gpio_write(D6, LOW);
            bcm2835_gpio_write(D7, LOW);
            break;

        case 4:
            bcm2835_gpio_write(D4, LOW);
            bcm2835_gpio_write(D5, LOW);
            bcm2835_gpio_write(D6, HIGH);
            bcm2835_gpio_write(D7, LOW);
            break;

        case 5:
            bcm2835_gpio_write(D4, HIGH);
            bcm2835_gpio_write(D5, LOW);
            bcm2835_gpio_write(D6, HIGH);
            bcm2835_gpio_write(D7, LOW);
            break;

        case 6:
            bcm2835_gpio_write(D4, LOW);
            bcm2835_gpio_write(D5, HIGH);
            bcm2835_gpio_write(D6, HIGH);
            bcm2835_gpio_write(D7, LOW);
            break;

        case 7:
            bcm2835_gpio_write(D4, HIGH);
            bcm2835_gpio_write(D5, HIGH);
            bcm2835_gpio_write(D6, HIGH);
            bcm2835_gpio_write(D7, LOW);
            break;

        case 8:
            bcm2835_gpio_write(D4, LOW);
            bcm2835_gpio_write(D5, LOW);
            bcm2835_gpio_write(D6, LOW);
            bcm2835_gpio_write(D7, HIGH);
            break;

        case 9:
            bcm2835_gpio_write(D4, HIGH);
            bcm2835_gpio_write(D5, LOW);
            bcm2835_gpio_write(D6, LOW);
            bcm2835_gpio_write(D7, HIGH);
            break;

        case 10:
            bcm2835_gpio_write(D4, LOW);
            bcm2835_gpio_write(D5, HIGH);
            bcm2835_gpio_write(D6, LOW);
            bcm2835_gpio_write(D7, HIGH);
            break;

        case 11:
            bcm2835_gpio_write(D4, HIGH);
            bcm2835_gpio_write(D5, HIGH);
            bcm2835_gpio_write(D6, LOW);
            bcm2835_gpio_write(D7, HIGH);
            break;

        case 12:
            bcm2835_gpio_write(D4, LOW);
            bcm2835_gpio_write(D5, LOW);
            bcm2835_gpio_write(D6, HIGH);
            bcm2835_gpio_write(D7, HIGH);
            break;

        case 13:
            bcm2835_gpio_write(D4, HIGH);
            bcm2835_gpio_write(D5, LOW);
            bcm2835_gpio_write(D6, HIGH);
            bcm2835_gpio_write(D7, HIGH);
            break;

        case 14:
            bcm2835_gpio_write(D4, LOW);
            bcm2835_gpio_write(D5, HIGH);
            bcm2835_gpio_write(D6, HIGH);
            bcm2835_gpio_write(D7, HIGH);
            break;

        case 15:
            bcm2835_gpio_write(D4, HIGH);
            bcm2835_gpio_write(D5, HIGH);
            bcm2835_gpio_write(D6, HIGH);
            bcm2835_gpio_write(D7, HIGH);
            break;
    }
}

void pulse_enable_line(void)
{
    bcm2835_gpio_write(En, HIGH);
    bcm2835_delayMicroseconds(1);
    bcm2835_gpio_write(En, LOW);
    bcm2835_delayMicroseconds(1);
}

void send_nyble(uint8_t data)
{
    assign_bits(data);
    bcm2835_delayMicroseconds(10);
    pulse_enable_line();
}

void send_byte(uint8_t data)
{
    send_nyble(data >> 4);
    bcm2835_delayMicroseconds(10);
    send_nyble(data & 0x0F);
    bcm2835_delayMicroseconds(10);
}

void write_inst(uint8_t data)
{
    lcd_gpio_low();
    bcm2835_delayMicroseconds(1);
    send_byte(data);
    bcm2835_delayMicroseconds(10);
}

