Cần một vài lời khuyên và phản hồi về thiết kế mã của tôi Tôi đang tìm phản hồi về thiết kế chương trình của tôi. Tôi có một tập lệnh shell gọi là function.sh định nghĩa rất nhiều hàm trợ giúp. Mục tiêu của tôi là sử dụng các hàm bash được định nghĩa trong functions.sh trong một chương trình C. Tôi làm điều này để tôi không phải viết lại chức năng bash (trong functions.sh) một lần nữa trong C. Tôi muốn sử dụng một thư viện chung cho các hàm tôi cần (đó là functions.sh). Đây là mã C và functions.sh của tôi:

Mã C:

#include <stdlib.h>
#include <sys/wait.h>
#include <stdio.h>

void shellCall(char *command)
{
    int status, commandexitcode = 0;

    if (command == NULL)
    {
        printf("Dòng lệnh NULL được gửi\n");
        exit(1);
    }

    status = system(command);

    if (status == -1)
    {
        printf("Lỗi khi gọi, giá trị %d\n", status);
        exit(1);
    }

    if (WIFEXITED(status))
    {
        commandexitcode = WEXITSTATUS(status);

        if (commandexitcode != 0)
        {
            printf("mã thoát không bằng không: %d\n", commandexitcode);
            exit(1);
        }
    }
    else
    {
        if (WIFSIGNALED(status))
        ...
    }
}

int main(int argc, char **argv)
{
    char command[100]; //lệnh
    int i = 0;

    for (i = 1; i <= 10; i++)
    {
        sprintf(command, "source $PWD/functions.sh; i=%d; myfunc %d", i, i);
        shellCall(command);
    }
}

