Thiết kế một API cho các hoạt động dịch vụ với các tham số liên quan chặt chẽ Tôi đang gặp khó khăn trong việc quyết định cách thiết kế API dịch vụ này.

public class GetCurrentValuesRequest
{
    public int ReferenceID { get; set; }

    public int[] FilterIDs { get; set; }
}

public class GetDefaultValuesRequest
{
    public int[] FilterIDs { get; set; }
}

public class GetValuesAsOfDateRequest
{
    public int ReferenceID { get; set; }

    public int[] FilterIDs { get; set; }

    public DateTime AsOf { get; set; }
}

public class GetValuesAsOfChangeSetRequest
{
    public int ReferenceID { get; set; }

    public int[] FilterIDs { get; set; }

    public long ChangeSetIDs { get; set; }
}

public class GetProposedValuesRequest
{
    public int ReferenceID { get; set; }

    public int[] FilterIDs { get; set; }

    public long ApprovalKey { get; set; }
}

public class GetValuesIfModifiedRequest
{
    public int ReferenceID { get; set; }

    public int[] FilterIDs { get; set; }

    public DateTime Since { get; set; }
}

public class GetValuesResponse
{
    public string[] Results { get; set; }
}

public class GetValuesIfModifiedResponse
{
    public string[] Results { get; set; }

    public bool IsModified { get; set; }
}

public interface IService
{
    GetValuesResponse GetValues(GetCurrentValuesRequest request);

    GetValuesResponse GetValues(GetDefaultValuesRequest request);

    GetValuesResponse GetValues(GetValuesAsOfDateRequest request);

    GetValuesResponse GetValues(GetValuesAsOfChangeSetRequest request);

    GetValuesResponse GetValues(GetProposedValuesRequest request);

    GetValuesIfModifiedResponse GetValuesIfModified(GetValuesIfModifiedRequest request);
}

Tôi đã nghĩ đến việc thay đổi nó để biến các yêu cầu/phản hồi IfModified thành các lớp con của yêu cầu/phản hồi GetValues đơn giản và chỉ bao gồm một cuộc gọi GetValues. Máy chủ sẽ trả về phản hồi khác nhau tùy thuộc vào yêu cầu đầu vào, nhưng điều đó yêu cầu người dùng gọi IService như sau:

var response = (GetValuesIfModifiedResponse)serviceClient.GetValues(new GetValuesIfModifiedRequest() { ... });

Tôi cũng đã nghĩ đến việc đặt IsModified trong GetValuesResponse đơn giản và chỉ điền vào nó nếu GetValuesIfModifiedRequest được truyền vào nó. Tuy nhiên, điều đó có vẻ hơi kỳ lạ khi bao gồm nó trong kết quả từ một phương thức thực sự không làm gì với nó. Ngoài ra, nó có thể khiến người dùng bối rối nếu họ nhìn thấy nó và mong đợi có thể sử dụng nó trong mã của họ. bool? IsModified tốt hơn, nhưng tôi vẫn chưa hoàn toàn thuyết phục về điều đó. Bạn có đề xuất nào cho cách thiết kế tốt nhất cho API này không?

Mẫu thiết kế này được gọi là gì? Mã của tôi như sau:

/// <tóm tắt>
/// Đại diện cho lớp Record Locator
/// </tóm tắt>
công khai lớp RecordLocator: IRecordLocator
{
/// <tóm tắt>
/// Chuỗi định vị bản ghi, ví dụ: ZT8C4O
/// </tóm tắt>
công khai chuỗi tên {get; riêng đặt tư nhân;}

/// <tóm tắt>
/// Khởi tạo một trường hợp mới của lớp <see cref="RecordLocator"/>
/// </tóm tắt>
/// <param name="recordLocator">Chuỗi định vị bản ghi.</param>
riêng tư nhân RecordLocator (chuỗi recordLocator)
{
tên = recordLocator;
}

/// <tóm tắt>
/// Phân tích chuỗi định vị bản ghi được chỉ định.
/// </tóm tắt>
/// <param name="recordLocator">Chuỗi định vị bản ghi.</param>
/// <returns></returns>
công khai tĩnh IRecordLocator Parse (chuỗi recordLocator)
{
nếu (string.IsNullOrEmpty (recordLocator))
ném mới ArgumentNullException ("recordLocator");
nếu (recordLocator.Length! = 6)
ném mới ArgumentException ("recordLocator.Length! = 6");
trở về mới RecordLocator (recordLocator);
}
}

/// <tóm tắt>
/// Đại diện cho giao diện Record Locator
/// </tóm tắt>
công khai giao diện IRecordLocator: IHideObjectMembers
{
/// <tóm tắt>
/// Chuỗi định vị bản ghi, ví dụ: ZT8C4O
/// </tóm tắt>
chuỗi công khai tên {get;}
}

1. Mẫu thiết kế này được gọi là gì? Khi bạn có một lớp, mà tự khởi tạo (và có lẽ có một bộ xây dựng riêng tư)? Một ví dụ khác của điều này là lớp 'System.DateTime' của .NET framework.
2. Liệu việc thực hiện nó như vậy có ổn không?

Tổng quát hóa biến sử dụng bên trong mã Tôi muốn biết liệu đây có phải là một cách thực hành tốt để tổng quát hóa các biến (dùng một biến duy nhất để lưu trữ tất cả các giá trị). Hãy xem ví dụ đơn giản sau:

Strings querycre,queryins,queryup,querydel;
querycre = 'Create table XYZ ...';
execute querycre ;
queryins = 'Insert into XYZ ...';
execute queryins ;
